mapper.select:
select *
from (
    select rownum as rnum, SearchResult.*
    from (
        select *
        from class_history_list
        where chno is not null

        order by regDate desc
    ) SearchResult

    where rownum <= #{endRow}

)
where rnum >= #{startRow}

mapper.update:
update class_history
set class_history = #{class_history}
where chno = #{chno}
